def features(timestamps, covariates, context_length):
    d = pd.DatetimeIndex(timestamps)
    n = len(d)
    hour = np.asarray(d.hour, float) + np.asarray(d.minute, float) / 60.0
    dow = np.asarray(d.dayofweek, float)
    res = {}
    ph = hour / 24.0
    res['hour_sin'] = np.sin(2 * np.pi * ph)
    res['hour_cos'] = np.cos(2 * np.pi * ph)
    res['hour_sin2'] = np.sin(4 * np.pi * ph)
    res['hour_cos2'] = np.cos(4 * np.pi * ph)
    wph = (dow + ph) / 7.0
    res['week_sin'] = np.sin(2 * np.pi * wph)
    res['week_cos'] = np.cos(2 * np.pi * wph)
    res['weekend'] = np.asarray(dow >= 5, float)

    def clean(x):
        s = pd.Series(np.asarray(x, float))
        s = s.mask(s <= -100.0)
        s = s.interpolate(limit_direction='both')
        v = s.to_numpy()
        if np.any(~np.isfinite(v)):
            v = np.where(np.isfinite(v), v, 0.0)
        return v

    def znorm(x, cl):
        c = x[:max(1, cl)]
        m = np.nanmean(c)
        sd = np.nanstd(c)
        if not np.isfinite(m):
            m = 0.0
        if not np.isfinite(sd) or sd < 1e-08:
            sd = 1.0
        return np.clip((x - m) / sd, -6.0, 6.0)
    cov = covariates if covariates is not None else {}
    cleaned = {}
    for name in ['T', 'RH', 'AH']:
        if name in cov and cov[name] is not None and (len(np.asarray(cov[name])) == n):
            cleaned[name] = clean(cov[name])
        else:
            cleaned[name] = None
    for name, key in [('T', 't_z'), ('RH', 'rh_z'), ('AH', 'ah_z')]:
        if cleaned[name] is not None:
            res[key] = znorm(cleaned[name], context_length)
        else:
            res[key] = np.zeros(n)
    night = ((hour >= 21.0) | (hour <= 5.0)).astype(float)
    if cleaned['T'] is not None:
        t = cleaned['T']
        tm = pd.Series(t).rolling(25, center=True, min_periods=6).mean().to_numpy()
        tm = np.where(np.isfinite(tm), tm, t)
        anom = t - tm
        ac = anom[:max(1, context_length)]
        sd = np.nanstd(ac)
        if not np.isfinite(sd) or sd < 1e-08:
            sd = 1.0
        anom_z = np.clip(anom / sd, -6.0, 6.0)
        res['t_anom'] = anom_z
        res['night_stab'] = night * np.clip(-anom_z, 0.0, None)
    else:
        res['t_anom'] = np.zeros(n)
        res['night_stab'] = night * 0.0
    for k in res:
        res[k] = np.asarray(res[k], float)
    return res
